contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, uint newVal) public payable {
        // initialize MinSum with val, then lock the contract
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(newVal); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // general rule: after Initialized(), SetMinSum must revert and MinSum stays put
        assert(reverted && c.MinSum() == before);
    }

    receive() external payable {}
}

